-- Apresentações (PowerPoints exportados em PDF) das aulas teóricas AT1–AT22 de Neuroanatomia.
-- Os objetos são carregados e verificados no R2 antes desta migration remota.
-- other_format separa PowerPoints e compêndios dentro do tipo 'other',
-- como summary_format (0074) e bibliography_format (0065) fazem nos seus tipos.
ALTER TABLE material_catalog ADD COLUMN other_format TEXT CHECK (other_format IS NULL OR other_format IN ('slides', 'compendium'));

-- Aulas teóricas AT6–AT22; as teóricas ficam ordenadas antes das práticas.
